def photo(id,cls='',eager=False):
 p=next(x for x in photos if x['id']==id)
 date=p['captured'][:4]+'年（元画像の日時情報）' if p['captured'][0].isdigit() else '撮影時点未確認'
 return f'<figure class="photo {cls}"><button class="photo-open" data-photo="{id}" aria-label="{p["title"]}の写真を拡大"><img src="assets/{id}.webp" srcset="assets/{id}-small.webp 700w, assets/{id}.webp 1600w" sizes="(max-width:700px) 100vw, 60vw" width="{p["width"]}" height="{p["height"]}" alt="{p["title"]}。由布市提供の地域風景写真。" loading="{'eager' if eager else 'lazy'}" decoding="async" {('fetchpriority="high"' if eager else '')}><span class="zoom" aria-hidden="true">↗</span></button><figcaption>{p["title"]} <span>{date} · <a href="#photo-credits">写真：由布市</a></span></figcaption></figure>'
def bars(vals,cls=''):
 colors=['pink','blue','lime','orange']
 return '<div class="bars '+cls+'">'+''.join(f'<div class="bar-row {colors[i]}"><div class="bar-label"><span>{v["label"]}</span><strong>{v["value"]}<small>%</small></strong></div><div class="bar-track" aria-hidden="true"><span style="--value:{v["value"]}%"></span></div></div>' for i,v in enumerate(vals))+'</div>'
credits=''.join(f'<li><a href="{p["source"]}">{p["title"]}</a>：{p["captured"][:4]+"年（元画像の日時情報）" if p["captured"][0].isdigit() else "撮影時点未確認"}。</li>' for p in photos)
sourcecards=''.join(f'<article id="source-{s["id"]}"><p class="eyebrow">SOURCE 0{i+1}</p><h3>{s["title"]}</h3><dl><dt>時期</dt><dd>{s["period"]}</dd><dt>対象</dt><dd>{s["area"]}／{s["sample"]}</dd><dt>掲載指標</dt><dd>{s["question"]}。{s["multiple"]}。</dd><dt>掲載箇所</dt><dd>{s["page"]}</dd></dl><p>{s["limit"]}</p><a class="source-link" href="{s["source"]}" target="_blank" rel="noopener">原典のPDFを読む ↗</a></article>' for i,s in enumerate(S))
page='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090b0c"><title>湯布院へ、どう来る？｜交通を読む｜WORLD CO-CREATION ATLAS</title><meta name="description" content="湯布院の交通を3つの調査から読む。自家用車・鉄道・レンタカー・バスの数字を、対象・時期・設問を分けて可視化。写真と動くインフォグラフィックで読み解く交通分析特集。"><link rel="canonical" href="https://mobilitydlab.com/co-creation-atlas/yufuin-mobility/"><meta property="og:type" content="article"><meta property="og:title" content="湯布院へ、どう来る？｜交通を読む"><meta property="og:description" content="車、鉄道、バス。その数字が語ることと、まだ語れないこと。"><meta property="og:image" content="https://mobilitydlab.com/co-creation-atlas/yufuin-mobility/assets/street.webp"><meta property="og:url" content="https://mobilitydlab.com/co-creation-atlas/yufuin-mobility/"><link rel="preload" href="../assets/display.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="style.css?v=20261103"><script defer src="app.js?v=20261103"></script></head><body><a class="skip" href="#main">本文へスキップ</a><div class="reading-progress" aria-hidden="true"></div><header class="masthead"><a class="wordmark" href="../">ATLAS<span>WORLD CO-CREATION</span></a><span class="issue">MOBILITY ANALYSIS / 01</span><button id="motion-toggle" type="button" aria-pressed="false">動きを止める</button></header><main id="main"><section class="hero" id="top"><div class="hero-kicker"><span>大分・湯布院</span><span>DATA STORY / 2026.11.03</span></div><h1><span class="hero-en">YUFUIN.</span><span class="hero-ja">湯布院へ、<br><em>どう来る？</em></span></h1><div class="hero-photo">__HERO__<div class="photo-tag">BEYOND THE NUMBERS.</div></div><div class="hero-bottom"><p class="lead">車、鉄道、バス。<br>数字から、<strong>まちへの入口</strong>を考える。</p><p>人が歩き、店に立ち寄り、風景を楽しむ湯布院。<br>その手前にある「来る・降りる・巡る」を、<br>対象の異なる３つの調査から読み解きます。</p><a class="round-link" href="#arrival" aria-label="最初の交通調査を読む">↓</a></div></section><nav class="chapter-nav" aria-label="特集の目次"><a href="#arrival"><b>01</b> 湯布院への交通</a><a href="#comparison"><b>02</b> 数字の違いを読む</a><a href="#foreign"><b>03</b> 海外居住者の県内移動</a><a href="#next"><b>04</b> 次に確かめること</a></nav>
<section class="opening wrap"><p class="eyebrow">FIRST, THE TAKEAWAY</p><h2>車が中心。<br>でも、<em class="blue-text">車だけじゃない。</em></h2><div class="opening-copy"><p>2022年夏の由布院調査では、自家用車が51％。JRが21％、レンタカーが14％と続きました。到着手段ごとに、まちへ入る場所も、必要な案内も違います。</p><p class="scope-note"><b>この特集の読み方</b><br>３つの調査を平均したり、一つの円グラフにまとめたりしません。「どこで・いつ・誰に聞いたか」と一緒に読みます。</p></div></section>
<section class="study wrap" id="arrival"><div class="section-top"><span class="section-no pink-text">01</span><div><p class="eyebrow">YUFUIN / SUMMER 2022</p><h2>旅の入口は、<br><em class="pink-text">自家用車が51％。</em></h2></div><a class="source-chip" href="#source-summer">調査の条件・出典 ↗</a></div><p class="context">2022年8月11日〜9月17日／由布院地域の現地調査</p><div class="primary-grid"><div class="primary-stat"><div class="stat-title">自家用車</div><div class="giant pink-text">51<span>%</span></div><div class="dot-field" aria-hidden="true">__DOTS__</div><p class="micro">100個の点で表した51％。<br>点は実際の回答者・乗客を表していません。</p></div><div class="secondary-stats"><article class="mini-stat blue"><span>JR</span><div>21<small>%</small></div><p>駅から、まちへ。</p></article><article class="mini-stat lime"><span>レンタカー</span><div>14<small>%</small></div><p>駐車から、滞在へ。</p></article><div class="sample"><p>調査全体</p><div><b>1,023</b>組 <span>/</span> <b>2,565</b>人</div><p>交通手段の有効回答数は、掲載段落に記載がありません。</p></div></div></div><p class="important"><span>CHECK</span>上位３項目の抜粋です。<strong>残り14％を「観光バス」とは扱えません。</strong>2026年現在の全来訪者の構成比を示す数字でもありません。</p><div class="photo-pair">__TRAIN____LIFE__</div><div class="editor-note"><span>MDLの視点</span><p><strong>駐車場から歩く人と、駅から歩く人。</strong><br>到着手段の違いを、到着後の動線・荷物・案内の設計へつなぐことが次の問いです。</p></div></section>
<section class="comparison wrap" id="comparison"><div class="section-top"><span class="section-no lime-text">02</span><div><p class="eyebrow">SAME PLACE, DIFFERENT SURVEY</p><h2>51と86.1。<br><em class="lime-text">違いにも、理由がある。</em></h2></div></div><div class="compare-statement"><p>由布市の観光基本計画には、<br>自家用車<strong class="lime-text">86.1<small>%</small></strong></p><div><p class="eyebrow">由布院までの移動手段 / 962回答</p><p>2022年2月公表の計画に掲載された、別の調査です。前の51％との差を、そのまま「車利用が減った」と読むことはできません。</p><p class="micro">交通手段の調査実施時期・詳細な抽出条件は未確認。計画の公表年と、現地調査の実施年は別です。</p><a class="source-link" href="#source-plan">条件と原典を見る ↗</a></div></div>__PLANBARS__<p class="micro">各バーは0〜100％の同じ尺度。丸めにより合計は100.1％。レンタカー・貸切観光バスの独立項目はありません。</p><div class="compare-rule"><p class="eyebrow">DON'T MIX THE DENOMINATORS</p><h3>場所。時期。対象。設問。</h3><p>この４つがそろわなければ、<strong>数字の差を「変化」にしない。</strong></p></div></section>
<section class="photo-interlude">__MIST__<div><p class="eyebrow">LOOK BEYOND THE DESTINATION</p><h2>湯布院へ来る。<br>大分を巡る。<br><em>それは、別の問い。</em></h2></div></section>
<section class="study wrap" id="foreign"><div class="section-top"><span class="section-no blue-text">03</span><div><p class="eyebrow">OITA PREFECTURE / FY2025</p><h2>海外居住者は、<br><em class="blue-text">複数の足で。</em></h2></div><a class="source-chip" href="#source-foreign">調査の条件・出典 ↗</a></div><div class="scope-banner"><strong>大分県全域</strong><span>海外居住者 <b>200</b>人</span><span>複数回答</span></div><p class="body-lead">2025年度の県調査で聞いたのは、<strong>「大分県内で使った交通手段」</strong>。湯布院に来た人だけの調査ではありません。「海外居住者」は国籍ではなく、住んでいる場所による区分です。</p><div class="foreign-grid">__FOREIGN__</div><p class="important"><span>CHECK</span>一人が鉄道とバスの両方を使うこともあります。<strong>合計を100％にする円グラフにはできません。</strong>掲載は一部項目の抜粋です。</p><div class="photo-pair">__CARRIAGE____LAKE__</div></section>
<section class="unknown wrap"><p class="eyebrow">WHAT WE DON'T KNOW YET</p><h2>観光バスは、<br><em class="orange-text">何人？ 何台？</em></h2><div class="unknown-grid"><div class="unknown-mark" aria-hidden="true">?</div><div><h3>今の湯布院だけの数は、<br>この３資料では分かりません。</h3><p>県全体の貸切・観光バス20.5％を、湯布院の来訪者数に掛けることはできません。観光客数を座席数で割って台数を推計することも避けます。</p><p class="micro">「確認できない」は「来ていない」ではありません。分からない数字を埋めるより、必要な記録をそろえます。</p></div></div></section>
<section class="wrap next" id="next"><div class="section-top"><span class="section-no pink-text">04</span><div><p class="eyebrow">FROM DATA TO A BETTER JOURNEY</p><h2>「来る」を、<br><em class="pink-text">「過ごす」へ。</em></h2></div></div><p class="body-lead">ここからはMDLの分析・提案です。交通量の観測や施策の効果を確認した結果ではありません。</p><ol class="journey"><li><span>01</span><h3>来る</h3><p>出発地・交通手段・<br>到着時刻を記録</p></li><li><span>02</span><h3>降りる</h3><p>駅・駐車場・乗降場の<br>集中と待ち時間を確認</p></li><li><span>03</span><h3>巡る</h3><p>歩行・立寄り・荷物の<br>困りごとを把握</p></li><li><span>04</span><h3>戻る</h3><p>帰路・乗継ぎ・再乗車の<br>安心を確かめる</p></li></ol><div class="research-list"><article><b>01 / COUNT</b><h3>同じ日に、数える。</h3><p>平日・休日、季節、時間帯をそろえ、駐車場の入出庫、バス台数、乗降人数を把握する。</p></article><article><b>02 / CONNECT</b><h3>移動の前後をつなぐ。</h3><p>出発地・次の目的地、宿泊／日帰り、滞在時間を同じ調査票で聞く。個人を特定しない集計にする。</p></article><article><b>03 / TEST</b><h3>小さく試し、比べる。</h3><p>駐車・乗換え案内や荷物対応を試し、歩きやすさ・待ち時間・店舗への回遊を実測する。</p></article></div><div class="closing-photos">__SPRING____PATH__</div></section>
<section class="sources wrap" id="sources"><p class="eyebrow">EVIDENCE / OPEN THE ORIGINAL</p><h2>数字の裏側まで。</h2><p>確認日：2026年11月3日。調査の対象年はそれぞれ異なります。公式・原著の記述と、MDLの分析・提案を分けています。</p><div class="source-grid">__SOURCES__</div><details id="photo-credits"><summary>写真８点の出典・撮影時点・利用条件</summary><p>全８点は由布市フォトアルバムの実景写真です。地域の風景を伝えるもので、交通調査日の記録や現在の混雑・運行状況を示すものではありません。</p><p><a href="https://www.city.yufu.oita.jp/kankou/photomovie" target="_blank" rel="noopener">由布市の写真配布ページ・利用条件 ↗</a>：営利・非営利を問わず無償利用可能、データ自体の販売は禁止。写真提供：由布市フォトアルバム。撮影者の個人名は配布ページに記載なし。</p><ul>__CREDITS__</ul><p>縮小・WebP変換、表示枠に応じたトリミングを実施。拡大時は写真全体を表示します。日時は元画像に記録された情報であり、独立した撮影日の確認ではありません。生成画像は使用していません。</p><a href="photos.json">画像ごとの出典台帳（JSON）</a></details><div class="data-links"><a href="data.json" download>数値・調査条件を取得（JSON） ↓</a><a href="../">ATLASへ戻る ↗</a></div></section></main><footer><div class="footer-word">YUFUIN.<em>MOVE BETTER.</em></div><p>WORLD CO-CREATION ATLAS · MOBILITY DESIGN LAB<br>モビリティ分析 / 2026.11.03</p><a href="#top">ページの先頭へ ↑</a></footer><dialog id="photo-dialog" aria-label="地域写真の拡大"><button class="dialog-close" type="button" aria-label="写真を閉じる">閉じる ×</button><img alt=""><p></p><a href="#photo-credits">出典・利用条件</a></dialog></body></html>'''
replacements={'HERO':photo('street',eager=True),'DOTS':''.join('<i class="'+('on' if i<51 else '')+'"></i>' for i in range(100)),'TRAIN':photo('train'),'LIFE':photo('street-life'),'PLANBARS':bars(S[1]['values']),'MIST':photo('mist'),'CARRIAGE':photo('carriage'),'LAKE':photo('lake'),'SPRING':photo('spring'),'PATH':photo('path'),'SOURCES':sourcecards,'CREDITS':credits,'FOREIGN':''.join(f'<article class="foreign-card {c}"><span class="transport-no">0{i+1}</span><h3>{v["label"]}</h3><div class="foreign-value">{v["value"]}<small>%</small></div><div class="bar-track" aria-hidden="true"><span style="--value:{v["value"]}%"></span></div></article>' for i,(v,c) in enumerate(zip(S[2]['values'],['pink','blue','lime','orange'])))}
for k,v in replacements.items(): page=page.replace('__'+k+'__',v)
(P/'index.html').write_text(page)
